import { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';
import { useNavigate } from 'react-router-dom';

import { Skeleton } from 'components/Skeleton';
import { Heading } from 'components/UI';
import { useLastDataRefresh } from 'contexts/LastDataRefresh/LastDataRefresh';
import { useMediaQuery, usePageFilterApplied, usePageFilterData } from 'hooks';
import type { FilterForm } from 'models/Filters';
import { StyledSectionsContainer } from 'pages/pillars/ValueCreation/CommercialResults/components/Sections/PerformanceSection/PerformanceSection.styles';
import { StyledValueCreationPageContainer } from 'pages/pillars/ValueCreation/styles';
import { StyledMainContainer } from 'shared/Styles';
import { boldRichTextValues } from 'utils/i18n/richTextValues';

import { marketShareWaterfallConfig } from '../../../config';
import {
  PERFORMANCE_TOOL_PAGE_NAME,
  PERFORMANCE_TOOL_PATH,
} from '../../../constants';
import { hasBreakdownDimensionsApplied } from '../../../utils/marketShareTimePeriodAlert.utils';
import { DataGovernanceBanner } from '../../DataGovernaceBanner/DataGovernanceBanner';
import {
  BigNumbersSection,
  DriversSection,
  LineBarChartsSection,
} from '../../Sections';
import { WaterfallSection } from '../../Sections/Charts/WaterfallSection/WaterfallSection';
import { StyledPerformanceSectionHeader } from '../../Sections/PerformanceSection/PerformanceSection.styles';
import { useKpiDrillDownTimePeriod } from '../KpiDrillDown/useKpiDrillDownTimePeriod';
import { BIG_NUMBERS_DATA } from './__mocks__/BigNumbers';
import { kpiDrillDownTableMock_principal } from './__mocks__/Table';
import { WATERFALL_DATA } from './__mocks__/Waterfall';
import {
  REFRESH_DATE_SKELETON_PROPS,
  SEGMENTED_CONTROL_OPTIONS,
} from './constants';
import { useMarketShareGovernanceDates } from './hooks';
import { useLineBarChartData } from './hooks/useLineBarChartData/useLineBarChartData';
import { useTitles } from './hooks/useTitles/useTitles';
import { StyledRefreshDate } from './MarketshareOfficial.styles';

const getRefreshDataSource = (applied: FilterForm) =>
  hasBreakdownDimensionsApplied(applied) ? 'Anaplan' : 'BrewDat';

export const MarketShareOfficial = () => {
  const { formatMessage } = useIntl();
  const { applied } = usePageFilterApplied(PERFORMANCE_TOOL_PAGE_NAME);
  const { appliedDataFilters } = usePageFilterData(PERFORMANCE_TOOL_PAGE_NAME);
  const { lastDataRefreshKpisDateMonthYear } = useLastDataRefresh();
  const kpiGroupDtEnd =
    lastDataRefreshKpisDateMonthYear?.['market_share_official_total'];
  const navigate = useNavigate();
  const isLargeScreen = useMediaQuery('(min-width: 1440px)');
  const { brewDatDate, anaplanDate, isGovernanceDatesReady } =
    useMarketShareGovernanceDates();
  const { waterfallTitle, lineBarChartsTitle, pageTitle } = useTitles();
  const showDrivers = false;

  const governanceMessage = useMemo(
    () =>
      formatMessage(
        {
          id: 'ValueCreation.PerformanceTool.market_share.dataGovernanceBanner',
        },
        {
          brewDatDate,
          anaplanDate,
          ...boldRichTextValues,
        },
      ),
    [anaplanDate, brewDatDate, formatMessage],
  );

  const handleSeeUpdateStatus = useCallback(() => {
    navigate(`${PERFORMANCE_TOOL_PATH}/market-share/source-status`);
  }, [navigate]);

  const {
    timePeriodSelection,
    requestPeriodType,
    lineChartPeriodType,
    lineChartDtEnd,
    lineChartCutoffDate,
  } = useKpiDrillDownTimePeriod({
    applied,
    appliedDataFilters,
    kpiSlug: 'market_share',
    kpiGroupDtEnd,
  });

  const timePeriodDescription = timePeriodSelection?.description;
  const refreshDataSource = getRefreshDataSource(applied);
  const refreshDateTag = timePeriodDescription ? (
    <StyledRefreshDate>
      {timePeriodDescription} | {refreshDataSource}
    </StyledRefreshDate>
  ) : (
    <Skeleton {...REFRESH_DATE_SKELETON_PROPS} />
  );

  const { loading, error, data } = useLineBarChartData(
    requestPeriodType ?? (applied.period_type as string),
    (lineChartPeriodType as string) ?? (applied.period_type as string),
    (lineChartDtEnd as string) ?? (applied.dt_end as string),
    (lineChartCutoffDate as string) ?? kpiGroupDtEnd,
  );
  const waterfallChartsSection = (
    <>
      {showDrivers && <DriversSection title={waterfallTitle} measure="[ % ]" />}

      {!showDrivers && (
        <WaterfallSection
          title={waterfallTitle}
          data={WATERFALL_DATA}
          tableData={kpiDrillDownTableMock_principal}
          loading={false}
          error={null}
          config={marketShareWaterfallConfig}
          variant={isLargeScreen ? 'large' : 'small'}
          segmentedControlOptions={SEGMENTED_CONTROL_OPTIONS}
        />
      )}
    </>
  );

  return (
    <StyledValueCreationPageContainer>
      <StyledMainContainer $fullWidth data-testid="performance-section">
        <StyledPerformanceSectionHeader data-testid="performance-section-header">
          <Heading size="H3" data-testid="performance-section-title">
            {pageTitle}
          </Heading>
        </StyledPerformanceSectionHeader>
        {isGovernanceDatesReady && (
          <DataGovernanceBanner
            message={governanceMessage}
            onSeeUpdateStatus={handleSeeUpdateStatus}
            dataTestId="market-share-v2-data-governance-banner"
          />
        )}
        <StyledSectionsContainer>
          <BigNumbersSection
            variant="embedded"
            data={BIG_NUMBERS_DATA}
            loading={false}
            error={null}
            defaultSelected={0}
            title="Market Share Performance"
          />
          <LineBarChartsSection
            title={lineBarChartsTitle}
            measure="[ % ]"
            data={data}
            loading={loading}
            error={error}
            showLineDataLabels
            bottomTag={refreshDateTag}
          />
          {waterfallChartsSection}
        </StyledSectionsContainer>
      </StyledMainContainer>
    </StyledValueCreationPageContainer>
  );
};
